pnpm --dir apps/web test src/game/Game.test.tsx
pnpm --dir apps/web test src/routes/match.test.tsx
pnpm --dir apps/web test src/routes/Rematch.test.tsx src/fx/FxLayer.test.tsx
pnpm --dir apps/web typecheck
pnpm exec eslint apps/web/src/game apps/web/src/routes/match.test.tsx
